yamark.toml.text:
[embedded.upper]
formatter = { command = ["sh", "-c", "tr a-z A-Z", "{path}"], path_suffix = ".txt" }
[embedded.grow]
formatter = { command = ["sh", "-c", "cat; echo extra", "{path}"], path_suffix = ".txt" }
[embedded.fail]
formatter = { command = ["sh", "-c", "echo bad >&2; exit 1", "{path}"], path_suffix = ".txt" }
[embedded.empty]
formatter = { command = ["sh", "-c", "cat >/dev/null", "{path}"], path_suffix = ".txt" }
